CREATE DATABASE IF NOT EXISTS rajmudra_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE rajmudra_db;
DROP TABLE IF EXISTS order_items;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS customers;
DROP TABLE IF EXISTS reviews;
DROP TABLE IF EXISTS enquiries;
DROP TABLE IF EXISTS products;

CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY,category VARCHAR(50) NOT NULL,name VARCHAR(100) NOT NULL,description TEXT,price DECIMAL(10,2) NOT NULL,image VARCHAR(255),rating DECIMAL(2,1) DEFAULT 5.0,reviews_count INT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE customers(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,phone VARCHAR(20),email VARCHAR(100),address TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE orders(id INT AUTO_INCREMENT PRIMARY KEY,customer_id INT,total_amount DECIMAL(10,2) NOT NULL,payment_method VARCHAR(50),status VARCHAR(50) DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES customers(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_name VARCHAR(100) NOT NULL,price DECIMAL(10,2) NOT NULL,quantity INT NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE reviews(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,rating INT NOT NULL,review TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE enquiries(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(100) NOT NULL,phone VARCHAR(20) NOT NULL,product VARCHAR(100),message TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
